struct FrameSequence;
impl Keyword for FrameSequence {
    fn validate<'i>(&self, instance: &'i Value) -> Result<(), ValidationError<'i>> {
        if self.is_valid(instance) {
            Ok(())
        } else {
            Err(ValidationError::custom("frames require one request, index zero then increasing indices, and one terminal outcome at the end"))
        }
    }
    fn is_valid(&self, instance: &Value) -> bool {
        let Some(items) = instance.as_array() else {
            return false;
        };
        if items.is_empty() || items[0]["frame_index"] != 0 {
            return false;
        }
        let id = &items[0]["request_id"];
        if items.iter().any(|f| &f["request_id"] != id) {
            return false;
        }
        if !items.windows(2).all(|p| {
            p[0]["frame_index"]
                .as_u64()
                .zip(p[1]["frame_index"].as_u64())
                .is_some_and(|(a, b)| a < b)
        }) {
            return false;
        }
        let terminal = |f: &Value| {
            matches!(
                f["frame_type"].as_str(),
                Some("final_response" | "engine_error" | "cancelled")
            )
        };
        terminal(items.last().unwrap()) && !items[..items.len() - 1].iter().any(terminal)
    }
}

#[derive(Clone, Debug)]
struct InMemoryRetriever {
    schemas: HashMap<String, Value>,
}

struct StrictlyIncreasing {
    properties: Vec<String>,
}

impl Keyword for StrictlyIncreasing {
    fn validate<'i>(&self, instance: &'i Value) -> Result<(), ValidationError<'i>> {
        if self.is_valid(instance) {
            Ok(())
        } else {
            Err(ValidationError::custom(format!(
                "properties must be strictly increasing: {}",
                self.properties.join(" < ")
            )))
        }
    }

    fn is_valid(&self, instance: &Value) -> bool {
        let Some(object) = instance.as_object() else {
            return true;
        };
        let values = self
            .properties
            .iter()
            .map(|property| object.get(property).and_then(Value::as_f64))
            .collect::<Option<Vec<_>>>();
        values.is_none_or(|values| values.windows(2).all(|pair| pair[0] < pair[1]))
    }
}

// A custom vocabulary constraint, like x-ubu-strictly-increasing for objects.
struct IncreasingItems;
impl Keyword for IncreasingItems {
    fn validate<'i>(&self, instance: &'i Value) -> Result<(), ValidationError<'i>> {
        if self.is_valid(instance) {
            Ok(())
        } else {
            Err(ValidationError::custom(
                "array integers must be strictly increasing",
            ))
        }
    }
    fn is_valid(&self, instance: &Value) -> bool {
        instance.as_array().is_none_or(|items| {
            items.windows(2).all(|pair| {
                pair[0]
                    .as_u64()
                    .zip(pair[1].as_u64())
                    .is_none_or(|(a, b)| a < b)
            })
        })
    }
}

struct UniqueBy {
    property: String,
}

impl Keyword for UniqueBy {
    fn validate<'i>(&self, instance: &'i Value) -> Result<(), ValidationError<'i>> {
        if self.is_valid(instance) {
            Ok(())
        } else {
            Err(ValidationError::custom(format!(
                "array items must have unique `{}` values",
                self.property
            )))
        }
    }

    fn is_valid(&self, instance: &Value) -> bool {
        let Some(items) = instance.as_array() else {
            return true;
        };
        let mut seen = HashSet::new();
        items.iter().all(|item| {
            item.get(&self.property)
                .and_then(Value::as_str)
                .is_none_or(|value| seen.insert(value))
        })
    }
}

struct TimestampOrder {
    start: String,
    end: String,
}
impl Keyword for TimestampOrder {
    fn validate<'i>(&self, instance: &'i Value) -> Result<(), ValidationError<'i>> {
        if self.is_valid(instance) {
            Ok(())
        } else {
            Err(ValidationError::custom("window end must be after start"))
        }
    }
    fn is_valid(&self, instance: &Value) -> bool {
        instance
            .get(&self.start)
            .and_then(Value::as_str)
            .zip(instance.get(&self.end).and_then(Value::as_str))
            .is_none_or(|(start, end)| timestamp_order::strictly_before(start, end))
    }
}

impl Retrieve for InMemoryRetriever {
    fn retrieve(&self, uri: &Uri<String>) -> Result<Value, Box<dyn Error + Send + Sync>> {
        let raw = uri.as_str();
        let base = raw.split('#').next().unwrap_or(raw);
        self.schemas
            .get(raw)
            .or_else(|| self.schemas.get(base))
            .cloned()
            .ok_or_else(|| format!("unregistered schema URI blocked: {raw}").into())
    }
}

